import { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { X, CheckCircle, AlertCircle, Info, AlertTriangle, Loader2 } from 'lucide-react';

interface Toast {
  id: string;
  type: 'success' | 'error' | 'warning' | 'info' | 'loading';
  title: string;
  message?: string;
  action?: { label: string; onClick: () => void };
  duration?: number;
  dismissible?: boolean;
}

interface ToastProviderProps {
  children: React.ReactNode;
  position?: 'top-right' | 'top-left' | 'bottom-right' | 'bottom-left' | 'top-center' | 'bottom-center';
  maxToasts?: number;
}

const positions = {
  'top-right': 'top-4 right-4',
  'top-left': 'top-4 left-4',
  'bottom-right': 'bottom-4 right-4',
  'bottom-left': 'bottom-4 left-4',
  'top-center': 'top-4 left-1/2 -translate-x-1/2',
  'bottom-center': 'bottom-4 left-1/2 -translate-x-1/2',
};

const typeStyles = {
  success: 'border-emerald-500/30 bg-emerald-500/10',
  error: 'border-rose-500/30 bg-rose-500/10',
  warning: 'border-amber-500/30 bg-amber-500/10',
  info: 'border-cyan-500/30 bg-cyan-500/10',
  loading: 'border-violet-500/30 bg-violet-500/10',
};

const typeIcons = {
  success: CheckCircle,
  error: AlertCircle,
  warning: AlertTriangle,
  info: Info,
  loading: Loader2,
};

const ToastContext = React.createContext<{
  toasts: Toast[];
  addToast: (toast: Omit<Toast, 'id'>) => string;
  removeToast: (id: string) => void;
  updateToast: (id: string, updates: Partial<Toast>) => void;
} | null>(null);

export function ToastProvider({
  children,
  position = 'top-right',
  maxToasts = 5,
}: ToastProviderProps) {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const addToast = useCallback((toast: Omit<Toast, 'id'>) => {
    const id = Math.random().toString(36).slice(2, 9);
    const newToast = { ...toast, id };
    setToasts(prev => [...prev.slice(-maxToasts + 1), newToast]);

    if (toast.duration !== 0 && toast.type !== 'loading') {
      setTimeout(() => removeToast(id), toast.duration ?? 5000);
    }
    return id;
  }, [maxToasts]);

  const removeToast = useCallback((id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const updateToast = useCallback((id: string, updates: Partial<Toast>) => {
    setToasts(prev => prev.map(t => t.id === id ? { ...t, ...updates } : t));
  }, []);

  const portalTarget = typeof document !== 'undefined' ? document.body : null;

  return (
    <ToastContext.Provider value={{ toasts, addToast, removeToast, updateToast }}>
      {children}
      {portalTarget && createPortal(
        <div className={`fixed z-[100] flex flex-col gap-2 ${positions[position]} pointer-events-none`}>
          {toasts.map(toast => (
            <ToastElement key={toast.id} toast={toast} onDismiss={removeToast} />
          ))}
        </div>,
        portalTarget
      )}
    </ToastContext.Provider>
  );
}

function ToastElement({ toast, onDismiss }: { toast: Toast; onDismiss: (id: string) => void }) {
  const [visible, setVisible] = useState(true);
  const Icon = typeIcons[toast.type];

  useEffect(() => {
    const timer = setTimeout(() => {
      setVisible(false);
      setTimeout(() => onDismiss(toast.id), 300);
    }, 300);
    return () => clearTimeout(timer);
  }, []);

  const handleDismiss = () => {
    if (toast.dismissible !== false) {
      setVisible(false);
      setTimeout(() => onDismiss(toast.id), 300);
    }
  };

  if (!visible) return null;

  return (
    <div
      className={`pointer-events-auto flex items-start gap-3 min-w-[300px] max-w-md p-4 rounded-xl border shadow-2xl backdrop-blur-xl animate-slide-in ${typeStyles[toast.type]}`}
      role="alert"
      aria-live="polite"
    >
      <div className="flex-shrink-0 mt-0.5">
        {toast.type === 'loading' ? (
          <Icon className="w-5 h-5 text-violet-400 animate-spin" />
        ) : (
          <Icon className={`w-5 h-5 ${toast.type === 'success' ? 'text-emerald-400' : toast.type === 'error' ? 'text-rose-400' : toast.type === 'warning' ? 'text-amber-400' : 'text-cyan-400'}`} />
        )}
      </div>
      <div className="flex-1 min-w-0">
        <p className="font-medium text-white">{toast.title}</p>
        {toast.message && <p className="text-sm text-gray-400 mt-0.5">{toast.message}</p>}
        {toast.action && (
          <button
            onClick={() => { toast.action!.onClick(); onDismiss(toast.id); }}
            className="mt-2 text-sm font-medium text-violet-400 hover:text-violet-300 underline"
          >
            {toast.action.label}
          </button>
        )}
      </div>
      {toast.dismissible !== false && (
        <button
          onClick={handleDismiss}
          className="flex-shrink-0 p-1 text-gray-400 hover:text-white transition-colors"
          aria-label="Dismiss"
        >
          <X className="w-4 h-4" />
        </button>
      )}
    </div>
  );
}

export function useToast() {
  const context = React.useContext(ToastContext);
  if (!context) throw new Error('useToast must be used within ToastProvider');
  return context;
}

// Convenience functions (if using outside React context)
export const toast = {
  success: (title: string, message?: string, options?: Partial<Toast>) => ({ type: 'success' as const, title, message, ...options }),
  error: (title: string, message?: string, options?: Partial<Toast>) => ({ type: 'error' as const, title, message, ...options }),
  warning: (title: string, message?: string, options?: Partial<Toast>) => ({ type: 'warning' as const, title, message, ...options }),
  info: (title: string, message?: string, options?: Partial<Toast>) => ({ type: 'info' as const, title, message, ...options }),
  loading: (title: string, message?: string, options?: Partial<Toast>) => ({ type: 'loading' as const, title, message, duration: 0, ...options }),
};

