addToast(toast.success('Saved!', 'Your changes have been saved.'));
addToast(toast.error('Failed', 'Something went wrong.', { action: { label: 'Retry', onClick: retry } }));
addToast(toast.loading('Processing...', 'Please wait', { duration: 0 }));
